import{_ as o,a0 as s,w as u,s as r,ao as l,I as i,x as t,a1 as p,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Juju 冰淇淋圖標設計 | LCTT x X-CMD","titleTemplate":false,"description":"Juju 冰淇淋圖標設計 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Juju 冰淇淋圖標設計 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Juju 冰淇淋圖標設計 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/Juju ice-cream icon design","title":"Juju 冰淇淋圖標設計","tag":"201401","desc":""},"relativePath":"201401/Juju ice-cream icon design.md","filePath":"[post].md"}'),c={name:"201401/Juju ice-cream icon design.md"};function m(d,e,j,g,h,f){const a=s("Link");return u(),r("div",null,[e[11]||(e[11]=l('<h1 id="juju-冰淇淋圖標設計" tabindex="-1">Juju 冰淇淋圖標設計 <a class="header-anchor" href="#juju-冰淇淋圖標設計" aria-label="Permalink to “Juju 冰淇淋圖標設計”">​</a></h1><p>有哪個人會不喜歡冰淇淋？作為設計團隊我們當然喜歡！在過去幾周的時間裏我們一直在為香港舉辦的開源架構會議準備一場特別的 Juju 演示，並且我們已經為之設計了一些非常“美味的”圖標。我們認為向大家展示這些圖標的創作過程是很美妙的，以下是這個設計流程的一些簡介。</p><h3 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to “摘要”">​</a></h3><p>我們想要用一些稍微有點特別的圖標去替換常規的 Juju 圖標，向人們闡述獨立訪問 Ubuntu 時 Juju 可以做些什麼事情。我們決定用帶有點綴物和醬調味的冰淇淋這個想法，你可以用同樣的方法打造在 Juju 上打造的服務。</p><p>這場演示最棒的環節是人們將在現實中真實地得到他們在 Juju 中&#39;打造&#39;的冰淇淋！</p><p><img src="http://design.canonical.com/wp-content/uploads/1-juju.jpg" alt=""></p><p><em>使用默認圖標的 Juju 界面</em></p><h3 id="尋找好的想法" tabindex="-1">尋找好的想法 <a class="header-anchor" href="#尋找好的想法" aria-label="Permalink to “尋找好的想法”">​</a></h3><p>我需要做的第一件事情是找到一個好的想法以圖標的形式表現帶有點綴物的冰淇淋。點綴物將被設計的非常精巧，以致它們將非常小並且很難製作成較小的尺寸。</p><p>最初我以縮略圖和設計思想的方式使用一種扁平外觀的圖標。這種方式對冰激凌來説很有用，但是對點綴物作用不大 —— 不久之後我發現它們變成半分離的現代主義，很難辨認。</p><p><img src="http://design.canonical.com/wp-content/uploads/1-juju-icecream-sketches-flat.jpg" alt=""></p><p><img src="http://design.canonical.com/wp-content/uploads/3-juju-icecream-flat-icons.jpg" alt=""></p><p><em>扁平簡潔化外觀的初始縮略圖與設計理念</em></p><p>在第二階段，我給圖標添加了透視效果；圖標保持一樣的透視連貫性是很重要的。</p><p><img src="http://design.canonical.com/wp-content/uploads/4-juju-icecream-sketches-perspective.jpg" alt=""></p><p><em>另一套添加透視效果的縮略圖</em></p><p>醬調味瓶的外觀也有些誤差，需要一定的試驗。最初的設計看起來非常像是瓶裝番茄醬，於是我們決定嘗試另一種不同的風格。</p><p><img src="http://design.canonical.com/wp-content/uploads/5-juju-icecream-sauce-shape.jpg" alt=""></p><p><em>調味醬外觀變化前後</em></p><p>至於背景，我選擇用閃亮的顏色來搭配冰淇淋圖標，以此與冰淇淋單色調形成對比，點綴物使用稍淡顏色，這全部整合起來就非常多彩豔麗了。</p><p>為圖標添加的眾多細節對於我們需要展示的以及圖標本身的辨認來説已經足夠了。我同樣添加了更大尺寸的點綴物，以使它們變得更加容易辨認。</p><p><img src="http://design.canonical.com/wp-content/uploads/6-juju-oreo-topping.jpg" alt=""></p><p><em>帶有破碎奧利奧的點綴物圖標</em></p><h3 id="編制細節" tabindex="-1">編制細節 <a class="header-anchor" href="#編制細節" aria-label="Permalink to “編制細節”">​</a></h3><p>破碎的奧利奧由單一的餅乾而來，我將之分成 9 個不同的部分然後散佈在不同層 —— 我猜在現實生活中也是這樣的。</p><p><img src="http://design.canonical.com/wp-content/uploads/7-juju-oreo-bits.jpg" alt=""></p><p><em>創立圖標所使用的 9 個分佈層</em></p><p>Inkscape 中的克隆工具得到了用武之地：在不同分佈層上重複同樣的小尺寸使得最後的 SVG 文件更加輕巧，也使 Inkscape 運行得更快。</p><p>從最初設計到最後圖標完成整個過程花費了 4 天的時間，差點超過預訂的限期，但這確實是一個應該繼續下去的有趣項目。</p><p><img src="http://design.canonical.com/wp-content/uploads/8-final-juju-icecream-icon-set.jpg" alt=""></p><p><em>最終圖標設計</em></p><hr>',32)),i("p",null,[e[1]||(e[1]=t("via: ",-1)),p(a,{href:"http://design.canonical.com/2013/11/juju-ice-cream-icon-design/"},{default:n(()=>[...e[0]||(e[0]=[t("http://design.canonical.com/2013/11/juju-ice-cream-icon-design/",-1)])]),_:1})]),i("p",null,[e[4]||(e[4]=t("譯者：",-1)),p(a,{href:"https://github.com/SteveArcher"},{default:n(()=>[...e[2]||(e[2]=[t("SteveArcher",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),p(a,{href:"https://github.com/wxy"},{default:n(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=t("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),p(a,{href:"http://linux.cn/"},{default:n(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const C=o(c,[["render",m]]);export{x as __pageData,C as default};
